const RESEARCH_PATHS={
 economy:[['eco_output'],['eco_discount'],['eco_speed'],['eco_storage','eco_recovery']],
 rockets:[['rocket_efficiency'],['rocket_line','rocket_propulsion'],['rocket_payload'],['rocket_capacity','rocket_piercing','rocket_burst','rocket_decoy','missile_breaker','missile_siege','missile_fast']],
 defense:[['shield_efficiency'],['shield_charge','shield_duration'],['shield_strength','shield_capacity'],['shield_anti_fast','shield_anti_heavy','shield_emergency']],
 intel:[['node_intel','sabotage_detection'],['node_logistics','node_deploy','node_reinforce'],['sabotage_economy','sabotage_industry','sabotage_shield','sabotage_node','sabotage_counter','sabotage_decoy'],['node_fortify','node_reserve','node_retreat','node_income']]
};
const RESEARCH_BRANCH_LABELS={economy:'ECONOMÍA',rockets:'COHETES',defense:'DEFENSA',intel:'INVESTIGACIÓN'};
function researchPathInfo(k){for(const [branch,tiers] of Object.entries(RESEARCH_PATHS)){const tier=tiers.findIndex(ids=>ids.includes(k));if(tier>=0)return {branch,tier:tier+1,tiers};}if(['recon','logistics'].includes(k))return{branch:'intel',tier:1,tiers:RESEARCH_PATHS.intel};return null;}
function researchCountForBranch(branch){return S.research.filter(k=>researchPathInfo(k)?.branch===branch).length;}
function researchLockReason(k){const branch=researchPathInfo(k)?.branch;return branch&&researchCountForBranch(branch)>=4?`Límite de 4 investigaciones en ${RESEARCH_BRANCH_LABELS[branch]}`:'';}
const BUILDINGS={
 generator:{name:'Generadores',base:120,growth:1.55,desc:'Produce Energía',icon:'⚡'},
 refinery:{name:'Refinerías',base:140,growth:1.58,desc:'Produce Acero',icon:'▣'},
 lab:{name:'Laboratorios',base:180,growth:1.62,desc:'Produce Intel',icon:'⌁'},
 automation:{name:'Automatización',base:220,growth:1.65,desc:'Produce Créditos',icon:'◈'}
};
const $=id=>document.getElementById(id); const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const fmt=n=>Math.floor(Number(n||0)).toLocaleString('es-AR');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let client=null,user=null,online=false,profile=null,saveTimer=null;
let S=loadLocal();
function defaults(){return {version:'1.5.2',nickname:'Factory-Local',currentCiv:null,civLocked:false,credits:400,energy:220,steel:160,intel:0,fragments:0,dominion:0,dominionTier:1,warWins:0,buildings:{generator:1,refinery:1,lab:1,automation:1},research:[],activeDoctrine:null,contractsCompleted:0,lifetimeProduction:0,cycleProduction:0,bestIndustrialScore:0,prestigeCount:0,legacyNodes:0,civLegacies:{forge:0,bastion:0,swarm:0,nexus:0},loyalty:{forge:0,bastion:0,swarm:0,nexus:0},activeContract:null,lastTick:Date.now(),factionLocal:{forge:{pvp:0,industrial:0,operations:0},bastion:{pvp:0,industrial:0,operations:0},swarm:{pvp:0,industrial:0,operations:0},nexus:{pvp:0,industrial:0,operations:0}}};}
function loadLocal(){try{return {...defaults(),...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch(_){return defaults();}}
function persistLocal(){S.lastTick=Date.now();localStorage.setItem(KEY,JSON.stringify(S));}
function toast(msg,bad=false){const e=$('toast');e.textContent=msg;e.style.borderColor=bad?'#a64e54':'#3f657c';e.classList.add('show');setTimeout(()=>e.classList.remove('show'),3500);}
function legacyEfficiency(){let p=S.prestigeCount||0;return 1+Math.min(p,10)*.01+Math.min(Math.max(p-10,0),10)*.005+Math.max(p-20,0)*.0025;}
function civProdMult(){return S.currentCiv==='bastion'?1.08:1;}
function researchMult(){return S.research.includes('logistics')?1.08:1;}
function production(){const m=legacyEfficiency()*civProdMult()*researchMult();return {energy:.75*S.buildings.generator*m,steel:.42*S.buildings.refinery*m,intel:.018*S.buildings.lab*m,credits:.18*S.buildings.automation*m};}
const RESOURCE_META={credits:{name:'Créditos',icon:'◈'},energy:{name:'Energía',icon:'⚡'},steel:{name:'Acero',icon:'▣'},intel:{name:'Intel',icon:'⌁'}};
function buildingGain(k){const m=legacyEfficiency()*civProdMult()*researchMult(),rates={generator:.75,refinery:.42,lab:.018,automation:.18},res={generator:'energy',refinery:'steel',lab:'intel',automation:'credits'};return {resource:res[k],gain:rates[k]*m,current:rates[k]*S.buildings[k]*m,next:rates[k]*(S.buildings[k]+1)*m};}
function numRate(n){return n<.1?n.toFixed(3):n.toFixed(1);}
function tipSafe(s){return esc(String(s)).replace(/`/g,'&#96;');}
function industrialScore(){const levels=Object.values(S.buildings).reduce((a,b)=>a+b,0),legacyResearch=S.research.filter(k=>!RESEARCH[k]?.category).length,arenaResearch=S.research.length-legacyResearch;return Math.floor(Math.sqrt(S.lifetimeProduction+1)*9+levels*75+S.contractsCompleted*55+legacyResearch*90+arenaResearch*25+S.prestigeCount*250);}
function prestigeProgress(){const levels=Object.values(S.buildings).reduce((a,b)=>a+b,0),a=clamp(levels/20,0,1),b=clamp(S.cycleProduction/12000,0,1),c=clamp(S.contractsCompleted/6,0,1),d=clamp(S.research.length/4,0,1);return Math.floor((a*.3+b*.3+c*.2+d*.2)*100);}
function canPrestige(){return prestigeProgress()>=100;}
function tick(){const now=Date.now(),dt=Math.min((now-(S.lastTick||now))/1000,4*3600);S.lastTick=now;if(dt<=0)return;const p=production(),produced=(p.energy+p.steel+p.credits)*dt;S.energy+=p.energy*dt;S.steel+=p.steel*dt;S.intel+=p.intel*dt;S.credits+=p.credits*dt;S.lifetimeProduction+=produced;S.cycleProduction+=produced;S.bestIndustrialScore=Math.max(S.bestIndustrialScore,industrialScore());if(S.activeContract&&now>=S.activeContract.endsAt)completeContract();persistLocal();}
function buildingCost(k){const b=BUILDINGS[k],lvl=S.buildings[k],base=b.base*Math.pow(b.growth,lvl-1),civ=S.currentCiv==='forge'?.90:1;return Math.round(base*civ);}
function upgradeBuilding(k){if(!S.currentCiv)return toast('Elegí una civilización primero.',true);const cost=buildingCost(k);if(S.credits<cost)return toast('Créditos insuficientes.',true);S.credits-=cost;S.buildings[k]++;S.bestIndustrialScore=Math.max(S.bestIndustrialScore,industrialScore());saveAll();render();toast(`${BUILDINGS[k].name} sube a nivel ${S.buildings[k]}.`);}
function researchCost(k){const branch=researchPathInfo(k)?.branch,count=branch?researchCountForBranch(branch):0,tierCosts=[90,135,190,255];let c=branch?tierCosts[Math.min(3,count)]:RESEARCH[k].cost;if(S.currentCiv==='nexus')c*=.9;if(S.research.includes('archive'))c*=.95;return Math.round(c);}
function isDoctrine(k){return ['missile_breaker','missile_siege','missile_fast'].includes(k);}
function civMastery(civ){return Math.min(10,(S.civLegacies[civ]||0)+(S.loyalty[civ]||0));}
function civPvpDescription(civ){const masteryBonus=civMastery(civ)*.5;switch(civ){case'forge':return `Mejoras económicas -${(7+masteryBonus).toFixed(1)}% costo · ataques +8% costo`;case'bastion':return `Escudos +${(14+masteryBonus).toFixed(1)}% resistencia · mejoras económicas +6% costo`;case'swarm':return `Ataques -${(12+masteryBonus).toFixed(1)}% costo · defensas +12% costo`;case'nexus':return `Sabotaje -${(26+masteryBonus).toFixed(1)}% costo · ataques +4% costo`;default:return CIVS[civ].pvp;}}
function equipDoctrine(k){if(!S.research.includes(k)||!isDoctrine(k))return;S.activeDoctrine=k;localStorage.setItem('factory-wars-v15-active-doctrine',k);saveAll();render();toast(`Doctrina equipada: ${RESEARCH[k].name}.`);}
function buyResearch(k){if(S.research.includes(k))return;const locked=researchLockReason(k);if(locked)return toast(locked,true);const c=researchCost(k);if(S.intel<c)return toast('Intel insuficiente.',true);S.intel-=c;S.research.push(k);if(isDoctrine(k)&&!S.activeDoctrine){S.activeDoctrine=k;localStorage.setItem('factory-wars-v15-active-doctrine',k);}saveAll();render();toast(`Investigación completada: ${RESEARCH[k].name}.`);}
function contractSpec(){const n=S.contractsCompleted,types=[['Suministro energético','energy',350+80*n,120+25*n],['Lote de acero','steel',240+60*n,135+28*n],['Paquete logístico','credits',220+45*n,45+8*n]];const x=types[n%types.length];return {name:x[0],resource:x[1],need:x[2],reward:x[3],seconds:Math.max(20,55+(n%4)*10)*(S.currentCiv==='swarm'?.9:1)};}
function startContract(){if(S.activeContract)return toast('Ya hay un contrato en curso.',true);const c=contractSpec();if(S[c.resource]<c.need)return toast(`Necesitás ${fmt(c.need)} de ${c.resource}.`,true);S[c.resource]-=c.need;S.activeContract={...c,endsAt:Date.now()+c.seconds*1000,id:`contract_${Date.now()}`};saveAll();render();}
function completeContract(){const c=S.activeContract;if(!c)return;S.credits+=c.reward;S.intel+=8;S.contractsCompleted++;S.activeContract=null;recordContribution('operations',25,`contract_${Date.now()}_${S.contractsCompleted}`);saveAll();toast(`Contrato completado: +${c.reward} créditos +8 Intel.`);}
async function recordContribution(kind,amount,eventId){if(!S.currentCiv)return;S.factionLocal[S.currentCiv][kind]=(S.factionLocal[S.currentCiv][kind]||0)+amount;if(online){try{await client.rpc('record_meta_contribution',{p_event_id:eventId,p_kind:kind,p_amount:amount});}catch(e){console.warn(e);}}}
function selectCiv(civ){if(S.civLocked&&S.currentCiv!==civ)return toast('Tu civilización está bloqueada hasta Prestigio 100%.',true);S.currentCiv=civ;S.civLocked=true;saveAll();render();toast(`Juraste lealtad a ${CIVS[civ].name}.`);}
async function doPrestige(nextCiv){if(!canPrestige())return toast('Todavía no llegaste a Prestigio 100%.',true);const old=S.currentCiv;S.prestigeCount++;S.legacyNodes++;S.civLegacies[old]=(S.civLegacies[old]||0)+1;if(nextCiv===old)S.loyalty[old]=(S.loyalty[old]||0)+1;else S.loyalty[nextCiv]=(S.loyalty[nextCiv]||0)+.5;await recordContribution('industrial',150,`prestige_${S.prestigeCount}_${Date.now()}`);S.credits=400;S.energy=220;S.steel=160;S.intel=Math.floor(S.intel*.35);S.fragments=Math.floor(S.fragments*.5);S.buildings={generator:1,refinery:1,lab:1,automation:1};S.research=S.research.includes('archive')?['archive']:[];S.activeDoctrine=null;localStorage.removeItem('factory-wars-v15-active-doctrine');S.contractsCompleted=0;S.cycleProduction=0;S.activeContract=null;S.currentCiv=nextCiv;S.civLocked=true;saveAll();$('prestigeModal').classList.remove('open');render();toast(`Ascensión completada. ${CIVS[old].name} conserva Legado +1; ${nextCiv===old?'repetir civilización suma maestría adicional.':'migrar suma maestría reducida a '+CIVS[nextCiv].name+'.'}`);}
function openPrestige(){if(!canPrestige())return toast('Completá los requisitos para ascender.',true);const box=$('prestigeChoices');box.innerHTML=Object.entries(CIVS).map(([id,c])=>`<button class="btn ${id===S.currentCiv?'good':'primary'}" data-prestige-civ="${id}">${id===S.currentCiv?'CONTINUAR':'MIGRAR A'} ${c.name}</button>`).join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>doPrestige(b.dataset.prestigeCiv));$('prestigeModal').classList.add('open');}
function saveAll(){persistLocal();clearTimeout(saveTimer);saveTimer=setTimeout(syncMeta,300);}
async function initOnline(){const ok=cfg.ONLINE_ENABLED&&cfg.SUPABASE_URL&&cfg.SUPABASE_PUBLISHABLE_KEY&&window.supabase?.createClient;if(!ok){$('onlineStatus').textContent='LOCAL · configurá Supabase para rankings compartidos';return;}try{client=window.supabase.createClient(cfg.SUPABASE_URL,cfg.SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true}});let {data:{session}}=await client.auth.getSession();if(!session){const x=await client.auth.signInAnonymously();if(x.error)throw x.error;session=x.data.session;}user=session.user;online=true;let q=await client.from('profiles').select('*').eq('user_id',user.id).maybeSingle();if(q.error)throw q.error;if(!q.data){const nick='Factory-'+user.id.replaceAll('-','').slice(0,6).toUpperCase();q=await client.from('profiles').insert({user_id:user.id,nickname:nick,season:cfg.SEASON||'BETA-IMPERIOS-01'}).select().single();if(q.error)throw q.error;}profile=q.data;S.nickname=profile.nickname;if(profile.current_civ&&!S.currentCiv){S.currentCiv=profile.current_civ;S.civLocked=true;}const meta=await client.from('industrial_states').select('*').eq('user_id',user.id).eq('season',cfg.SEASON).maybeSingle();if(meta.data)mergeRemote(meta.data);else await syncMeta();await loadLeagueRemote();ensureLeague();$('onlineStatus').textContent=`ONLINE · ${S.nickname} · ${cfg.SEASON}`;render();loadAllRankings();}catch(e){console.error(e);$('onlineStatus').textContent='LOCAL · error Supabase: '+e.message;}}
function mergeRemote(r){S.credits=Number(r.credits??S.credits);S.energy=Number(r.energy??S.energy);S.steel=Number(r.steel??S.steel);S.intel=Number(r.intel??S.intel);S.fragments=Number(r.fragments??S.fragments);S.buildings=r.buildings||S.buildings;S.research=r.research||S.research;S.contractsCompleted=r.contracts_completed??S.contractsCompleted;S.lifetimeProduction=Number(r.lifetime_production??S.lifetimeProduction);S.cycleProduction=Number(r.cycle_production??S.cycleProduction);S.bestIndustrialScore=Number(r.best_score??S.bestIndustrialScore);S.prestigeCount=r.prestige_count??S.prestigeCount;S.legacyNodes=Number(r.legacy_nodes??S.legacyNodes);S.civLegacies=r.civ_legacies||S.civLegacies;S.loyalty=r.loyalty||S.loyalty;S.lastTick=new Date(r.last_tick||Date.now()).getTime();persistLocal();}
async function syncMeta(){if(!online||!user)return;try{await client.from('profiles').update({nickname:S.nickname,season:cfg.SEASON,current_civ:S.currentCiv,prestige_count:S.prestigeCount,legacy_nodes:S.legacyNodes,civ_legacies:S.civLegacies,loyalty:S.loyalty,updated_at:new Date().toISOString()}).eq('user_id',user.id);const row={user_id:user.id,season:cfg.SEASON,credits:S.credits,energy:S.energy,steel:S.steel,intel:S.intel,fragments:S.fragments,buildings:S.buildings,research:S.research,contracts_completed:S.contractsCompleted,lifetime_production:S.lifetimeProduction,cycle_production:S.cycleProduction,best_score:Math.max(S.bestIndustrialScore,industrialScore()),prestige_count:S.prestigeCount,legacy_nodes:S.legacyNodes,civ_legacies:S.civLegacies,loyalty:S.loyalty,last_tick:new Date(S.lastTick).toISOString(),updated_at:new Date().toISOString()};const q=await client.from('industrial_states').upsert(row,{onConflict:'user_id,season'});if(q.error)throw q.error;}catch(e){console.warn('sync meta',e);}}
async function saveNickname(){const v=($('nicknameInput').value||'').trim();if(!/^[A-Za-z0-9_\-ÁÉÍÓÚÜÑáéíóúüñ ]{3,20}$/.test(v))return toast('Nickname de 3–20 caracteres.',true);S.nickname=v;saveAll();render();}
function warTierThreshold(){return 120 + Math.max(0, (S.dominionTier||1)-1)*80;}
function dominionProgress(){const next=warTierThreshold();const pct=Math.min(100, (S.dominion / next) * 100);return {next,pct};}
function grantDominionFromBattle(result){const base = result==='win'?36:result==='draw'?14:6;const civBoost = S.currentCiv ? (S.currentCiv==='forge'?1.12:S.currentCiv==='bastion'?1.08:S.currentCiv==='swarm'?1.1:S.currentCiv==='nexus'?1.14:1) : 1;const gain = Math.round(base * civBoost);S.dominion += gain;const next = warTierThreshold();if(S.dominion >= next){const extra = Math.floor(S.dominion / next);S.dominionTier += extra;S.dominion = S.dominion % next;toast(`Maestría de guerra +${extra}. Ahora estás en Nivel ${S.dominionTier}.`);}S.warWins += result==='win'?1:0;persistLocal();}
