function renderRankTable(id,view,rows){if(view==='faction_leaderboard'){$(id).innerHTML=rows.map((r,i)=>`<div class="faction-score"><b>#${i+1} ${CIVS[r.civ]?.name||r.civ}</b><div class="bar"><i style="width:${clamp(Number(r.faction_score||0),0,100)}%"></i></div><b>${Number(r.faction_score||0).toFixed(1)}</b></div><div class="fine">${r.players||0} activos · PvP ${Number(r.pvp_component||0).toFixed(1)} · Industria ${Number(r.industrial_component||0).toFixed(1)} · Operaciones ${Number(r.operations_component||0).toFixed(1)}</div>`).join('')||'<p>Sin contribuciones todavía.</p>';return;}const cols=view==='arena_leaderboard'?['nickname','rating','wins','games']:view==='industrial_leaderboard'?['nickname','industrial_score','prestige_count','best_score']:['nickname','empire_score','arena_percentile','industrial_percentile'];$(id).innerHTML=`<table class="rank"><thead><tr><th>#</th>${cols.map(c=>`<th>${c.replaceAll('_',' ')}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td>${cols.map(c=>`<td>${c==='nickname'?esc(r[c]):Number(r[c]||0).toFixed(c.includes('percentile')||c.includes('score')||c==='rating'?1:0)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
