function resetEverything(){if(!confirm('¿Borrar la civilización actual y todo el historial local de la temporada? Esto limpia el estado guardado en este navegador.'))return;localStorage.removeItem(KEY);localStorage.removeItem('factory-wars-v15-current-civ');localStorage.removeItem('factory-wars-v15-active-doctrine');localStorage.removeItem(LEAGUE_KEY);S=defaults();league=null;persistLocal();render();loadAllRankings();toast('Estado local borrado. Elegí una civilización nuevamente.');}
window.addEventListener('message',ev=>{const d=ev.data||{};if(d.type==='factory-wars-match-synced'&&d.reward){S.credits+=d.reward.credits||0;S.intel+=d.reward.intel||0;S.fragments+=d.reward.fragments||0;S.dominion+=Number(d.reward.dominion||0);if(S.currentCiv)S.factionLocal[S.currentCiv].pvp+=(d.reward.faction||0);if(S.dominion>0){const next=warTierThreshold();if(S.dominion>=next){const extra=Math.floor(S.dominion/next);S.dominionTier+=extra;S.dominion%=next;}}persistLocal();render();toast(`Arena → Megafábrica: +${d.reward.credits||0} créditos, +${d.reward.intel||0} Intel, +${Number(d.reward.dominion||0)} Dominio.`);}if(d.type==='fw-league-human-result')handleHumanLeagueResult(d);if(d.type==='fw-league-sim-results'&&league?.pending){const r=league.rounds[league.pending.round];if(r&&d.round===r.index)finishLeagueRound(d.results||[]);}if(d.type==='fw-arena-ready'&&league?.pending)requestBotSim();});

