function civOrderExcept(civ){return ['forge','bastion','swarm','nexus'].filter(x=>x!==civ);}
function makeLeague(){if(!S.currentCiv)return null;const civs=['forge','bastion','swarm','nexus'];const others=civOrderExcept(S.currentCiv);const seasonBots=LEAGUE_BOTS.map((b,i)=>({...b,civ:civs[i % civs.length],name:`${b.name}-${civs[i % civs.length].slice(0,3).toUpperCase()}`}));
 const bots=seasonBots.map((b,i)=>({
   ...b,
   civ: i < 2 ? S.currentCiv : (i % 2 === 0 ? others[(i-1) % others.length] : others[(i-2) % others.length]),
   industrial:0,
   operations:0,
   pvpContribution:0
 }));
 const players=[{id:'you',name:S.nickname,strategy:'HUMANO',civ:S.currentCiv,isHuman:true,rating:1000,games:0,wins:0,draws:0,losses:0,points:0,industrial:0,operations:0,pvpContribution:0},...bots.map(b=>({...b,isHuman:false,rating:1000,games:0,wins:0,draws:0,losses:0,points:0,industrial:0,operations:0,pvpContribution:0}))];
 const eligible=bots.filter(b=>b.civ!==S.currentCiv),pairCounts={};
 function pairKey(a,b){return [a,b].sort().join('|')}
 function pairRemaining(ids){if(!ids.length)return [];const a=ids[0],pa=players.find(p=>p.id===a),cands=ids.slice(1).filter(id=>players.find(p=>p.id===id).civ!==pa.civ).sort((x,y)=>(pairCounts[pairKey(a,x)]||0)-(pairCounts[pairKey(a,y)]||0));for(const b of cands){const rest=ids.filter(x=>x!==a&&x!==b),tail=pairRemaining(rest);if(tail){return [[a,b],...tail];}}return null;}
 const rounds=[];eligible.forEach((opp,r)=>{const remaining=bots.map(b=>b.id).filter(id=>id!==opp.id),pairs=pairRemaining(remaining)||[];pairs.forEach(([a,b])=>{const k=pairKey(a,b);pairCounts[k]=(pairCounts[k]||0)+1;});rounds.push({index:r+1,userOpponent:opp.id,matches:[['you',opp.id],...pairs],done:false,results:[]});});
 return {version:'1.6',season:cfg.SEASON||'BETA-IMPERIOS-01',createdAt:new Date().toISOString(),userCiv:S.currentCiv,round:0,players,rounds,pending:null,complete:false};
}
function ensureLeague(){if(!S.currentCiv){league=null;return null;}if(!league)league=loadLeague();if(!league||league.version!=='1.6'||!Array.isArray(league.players)||!Array.isArray(league.rounds)){league=makeLeague();saveLeague();}const me=league.players.find(p=>p.id==='you');if(me){me.name=S.nickname;me.industrial=Math.max(me.industrial||0,industrialScore());}return league;}
function leaguePlayer(id){return league?.players?.find(p=>p.id===id)||null;}
function currentLeagueRound(){return league&&!league.complete?league.rounds[league.round]:null;}
function currentOpponent(){const r=currentLeagueRound();return r?leaguePlayer(r.userOpponent):null;}
function eloApply(a,b,scoreA){const ea=1/(1+10**((b.rating-a.rating)/400)),eb=1-ea,K=32,ra=a.rating,rb=b.rating;a.rating=Math.round(ra+K*(scoreA-ea));b.rating=Math.round(rb+K*((1-scoreA)-eb));}
function applyLeagueResult(aId,bId,winner,duration=0){const a=leaguePlayer(aId),b=leaguePlayer(bId);if(!a||!b)return;const sa=winner===aId?1:winner===bId?0:.5;eloApply(a,b,sa);for(const [p,s] of [[a,sa],[b,1-sa]]){p.games++;if(s===1){p.wins++;p.points+=3;p.pvpContribution=(p.pvpContribution||0)+30;}else if(s===.5){p.draws++;p.points+=1;p.pvpContribution=(p.pvpContribution||0)+12;}else{p.losses++;p.pvpContribution=(p.pvpContribution||0)+8;}}return {a:aId,b:bId,winner,duration};}
function advanceBotFarms(roundIndex){for(const p of league.players){if(p.isHuman){p.industrial=Math.max(p.industrial||0,industrialScore());continue;}const civMult=p.civ==='forge'?1.08:p.civ==='bastion'?1.06:p.civ==='swarm'?1.02:1.04;const wave=1+(((roundIndex+LEAGUE_BOTS.findIndex(b=>b.id===p.id))%5)-2)*.025;p.industrial=Math.round((p.industrial||0)+p.farm*civMult*wave);p.operations=(p.operations||0)+(p.strategy==='SABOTEUR'?34:p.strategy==='BALANCED'?28:p.strategy==='RANDOM'?17:24);}}
function finishLeagueRound(botResults){const r=currentLeagueRound();if(!r||r.done)return;for(const x of botResults||[]){if(x.a&&x.b)r.results.push(applyLeagueResult(x.a,x.b,x.winner,x.duration));}advanceBotFarms(r.index);r.done=true;league.pending=null;league.round++;league.complete=league.round>=league.rounds.length;saveLeague();leagueAwaitingSim=false;render();loadAllRankings();toast(league.complete?'Liga 10 completada. Revisá los rankings finales.':`Fecha ${r.index} cerrada. Se desbloqueó la fecha ${league.round+1}.`);}
function startLeagueMatch(){if(!S.currentCiv)return toast('Elegí una civilización antes de entrar a la Liga.',true);ensureLeague();if(league.complete)return toast('La Liga 10 ya terminó. Podés reiniciarla desde Perfil.',true);if(league.pending)return toast('Esta fecha se está resolviendo.',true);const r=currentLeagueRound(),opp=currentOpponent(),f=$('arenaFrame');if(!f.src)f.src='./arena.html';const factoryProgress={civilization:S.currentCiv,research:[...S.research],researchCatalog:Object.fromEntries(S.research.filter(k=>RESEARCH[k]).map(k=>[k,{...RESEARCH[k]}])),activeDoctrine:S.activeDoctrine,civMastery:civMastery(S.currentCiv)};const send=()=>f.contentWindow?.postMessage({type:'fw-league-start',leagueMatchId:`${league.season}_R${r.index}`,round:r.index,userName:S.nickname,userCiv:league.userCiv,factoryProgress,opponent:{id:opp.id,name:opp.name,civ:opp.civ,strategy:opp.strategy}},'*');if(f.contentWindow){send();setTimeout(send,250);}else setTimeout(send,500);}
function requestBotSim(){if(!league?.pending||leagueAwaitingSim)return;const f=$('arenaFrame'),r=league.rounds[league.pending.round];if(!f?.contentWindow||!r)return;const specs=r.matches.slice(1).map(([a,b],i)=>{const pa=leaguePlayer(a),pb=leaguePlayer(b);return {a,b,civA:pa.civ,civB:pb.civ,botA:pa.strategy,botB:pb.strategy,seed:(league.pending.seed+i*104729)>>>0};});leagueAwaitingSim=true;f.contentWindow.postMessage({type:'fw-league-simulate',round:r.index,matches:specs},'*');setTimeout(()=>{leagueAwaitingSim=false;if(league?.pending)requestBotSim();},2500);}
function handleHumanLeagueResult(d){ensureLeague();const r=currentLeagueRound();if(!r||r.done||d.round!==r.index||league.pending)return;const opp=leaguePlayer(r.userOpponent),winner=d.result==='win'?'you':d.result==='loss'?opp.id:null;r.results.push(applyLeagueResult('you',opp.id,winner,d.duration));if(!online){const rw=d.result==='win'?{credits:180,intel:12,fragments:2,faction:30,dominion:36}:d.result==='draw'?{credits:100,intel:6,fragments:1,faction:12,dominion:14}:{credits:70,intel:4,fragments:0,faction:8,dominion:6};S.credits+=rw.credits;S.intel+=rw.intel;S.fragments+=rw.fragments;S.dominion+=Number(rw.dominion||0);if(S.currentCiv)S.factionLocal[S.currentCiv].pvp=(S.factionLocal[S.currentCiv].pvp||0)+rw.faction;const next=warTierThreshold();if(S.dominion>=next){const extra=Math.floor(S.dominion/next);S.dominionTier+=extra;S.dominion%=next;}persistLocal();}league.pending={round:league.round,seed:(d.seed||Date.now())>>>0};saveLeague();toast(`Tu partida terminó. Simulando las otras 4 partidas de la fecha ${r.index}…`);requestBotSim();}
function leagueStandings(){ensureLeague();if(!league)return[];const rows=league.players.map(p=>({...p,name:p.id==='you'?S.nickname:p.name,industrial:p.id==='you'?Math.max(p.industrial||0,industrialScore()):p.industrial}));return rows.sort((a,b)=>b.points-a.points||b.rating-a.rating||b.wins-a.wins);}
function percentileMap(rows,key){const sorted=[...rows].sort((a,b)=>(a[key]||0)-(b[key]||0)),out={};sorted.forEach((p,i)=>out[p.id]=sorted.length<=1?50:i/(sorted.length-1)*100);return out;}
function empireStandings(){const rows=leagueStandings(),a=percentileMap(rows,'rating'),ind=percentileMap(rows,'industrial');return rows.map(p=>({...p,arenaPct:a[p.id],industrialPct:ind[p.id],empire:a[p.id]*.6+ind[p.id]*.4})).sort((x,y)=>y.empire-x.empire);}
function factionLeagueRows(){ensureLeague();if(!league)return[];const sums={forge:{players:0,pvp:0,industrial:0,operations:0},bastion:{players:0,pvp:0,industrial:0,operations:0},swarm:{players:0,pvp:0,industrial:0,operations:0},nexus:{players:0,pvp:0,industrial:0,operations:0}};for(const p of league.players){const x=sums[p.civ];x.players++;x.pvp+=p.pvpContribution||0;x.industrial+=p.id==='you'?industrialScore():p.industrial||0;x.operations+=p.id==='you'?(S.factionLocal[p.civ]?.operations||0):p.operations||0;}const raw=Object.entries(sums).map(([c,x])=>({civ:c,...x,pvpR:x.pvp/Math.sqrt(Math.max(1,x.players)),indR:x.industrial/Math.sqrt(Math.max(1,x.players)),opsR:x.operations/Math.sqrt(Math.max(1,x.players))})),mp=Math.max(1,...raw.map(x=>x.pvpR)),mi=Math.max(1,...raw.map(x=>x.indR)),mo=Math.max(1,...raw.map(x=>x.opsR));return raw.map(x=>({...x,pvpComponent:x.pvpR/mp*100,industrialComponent:x.indR/mi*100,operationsComponent:x.opsR/mo*100,score:(x.pvpR/mp*100)*.45+(x.indR/mi*100)*.35+(x.opsR/mo*100)*.20})).sort((a,b)=>b.score-a.score);}
function civLabel(c){return `${CIVS[c]?.icon||''} ${CIVS[c]?.name||c}`;}
function renderLeagueArena(){const e=$('leagueArenaCard');if(!e)return;if(!S.currentCiv){e.innerHTML='<div class="league-done">Elegí una civilización para crear tu Liga 10.</div>';return;}ensureLeague();if(!league)return;if(league.complete){const pos=leagueStandings().findIndex(p=>p.id==='you')+1;e.innerHTML=`<div class="league-done">TEMPORADA COMPLETA · terminaste #${pos} de 10. Todos jugaron 8 partidas. Revisá Arena, Industrial, Imperio y Civilizaciones en RANKINGS.</div>`;return;}const r=currentLeagueRound(),o=currentOpponent(),me=leaguePlayer('you'),pct=league.round/8*100;e.innerHTML=`<div class="league-head"><div><small class="league-round">FECHA ${r.index} / 8</small><h2>Próximo PvP</h2></div><b>${me.games}/8 jugadas</b></div><div class="league-progress"><i style="width:${pct}%"></i></div><div class="league-duel"><div class="league-player"><small>VOS · ${civLabel(league.userCiv)}</small><b>${esc(S.nickname)}</b><em>${me.points} pts · Rating ${me.rating}</em></div><div class="league-vs">VS</div><div class="league-player enemy"><small>RIVAL · ${civLabel(o.civ)}</small><b>${esc(o.name)} <span class="bot-badge">BOT</span></b><em>${o.strategy} · ${o.points} pts · Rating ${o.rating}</em></div></div><div class="league-rule"><strong>Regla:</strong> el rival siempre pertenece a otra civilización. Su bonus de civilización afecta realmente costos/escudos/sabotaje dentro del motor PvP. Cuando termine tu partida, los otros 8 bots juegan 4 partidas y recién entonces avanza la fecha.</div><div class="league-actions"><button id="playLeagueRound" class="btn primary">⚔ JUGAR FECHA ${r.index}</button><span class="fine">No podés adelantar fechas sin jugar.</span></div>`;const b=$('playLeagueRound');if(b)b.onclick=startLeagueMatch;}
function renderLeagueSchedule(){const e=$('leagueSchedule');if(!e)return;if(!S.currentCiv){e.innerHTML='';return;}ensureLeague();e.innerHTML=league.rounds.map((r,i)=>{const o=leaguePlayer(r.userOpponent),cls=r.done?'done':i===league.round&&!league.complete?'current':'locked',res=r.results?.find(x=>x&&(x.a==='you'||x.b==='you')),label=res?(res.winner==='you'?'VICTORIA':res.winner===null?'EMPATE':'DERROTA'):(i===league.round&&!league.complete?'PRÓXIMA':'BLOQUEADA');return `<div class="round-chip ${cls}"><b>FECHA ${r.index} · ${label}</b>${civLabel(o.civ)} · ${esc(o.name)}<br><span>${o.strategy}</span></div>`}).join('');}
function renderLeagueRankings(){ensureLeague();if(!league)return;const rows=leagueStandings(),next=currentOpponent()?.id;$('arenaRank').innerHTML=`<table class="rank"><thead><tr><th>#</th><th>Jugador</th><th>Civ</th><th>Pts</th><th>Rating</th><th>W-D-L</th><th>J</th></tr></thead><tbody>${rows.map((p,i)=>`<tr class="${p.id==='you'?'me':''} ${p.id===next?'next-rival':''}"><td>${i+1}</td><td>${esc(p.name)}${p.isHuman?'':' <span class="bot-badge">'+p.strategy+'</span>'}</td><td><span class="civ-mini">${civLabel(p.civ)}</span></td><td class="league-score">${p.points}</td><td>${p.rating}</td><td>${p.wins}-${p.draws}-${p.losses}</td><td>${p.games}/8</td></tr>`).join('')}</tbody></table><div class="league-note">3 pts victoria · 1 empate · 0 derrota. Rating Elo como desempate. Todos avanzan una partida por fecha.</div>`;
 const ind=[...rows].sort((a,b)=>(b.id==='you'?industrialScore():b.industrial)-(a.id==='you'?industrialScore():a.industrial));$('industrialRank').innerHTML=`<table class="rank"><thead><tr><th>#</th><th>Jugador</th><th>Civ</th><th>Industrial</th></tr></thead><tbody>${ind.map((p,i)=>`<tr class="${p.id==='you'?'me':''}"><td>${i+1}</td><td>${esc(p.name)}${p.isHuman?'':' <span class="bot-badge">BOT</span>'}</td><td>${civLabel(p.civ)}</td><td>${fmt(p.id==='you'?industrialScore():p.industrial)}</td></tr>`).join('')}</tbody></table><div class="league-note">Los bots también farmean, pero su fábrica sólo progresa cuando vos cerrás una fecha.</div>`;
 const imp=empireStandings();$('empireRank').innerHTML=`<table class="rank"><thead><tr><th>#</th><th>Jugador</th><th>Imperio</th><th>Arena</th><th>Industria</th></tr></thead><tbody>${imp.map((p,i)=>`<tr class="${p.id==='you'?'me':''}"><td>${i+1}</td><td>${esc(p.name)}${p.isHuman?'':' <span class="bot-badge">BOT</span>'}</td><td class="league-score">${p.empire.toFixed(1)}</td><td>${p.arenaPct.toFixed(0)}%</td><td>${p.industrialPct.toFixed(0)}%</td></tr>`).join('')}</tbody></table><div class="league-note">Imperio = 60% percentil Arena + 40% percentil Industrial.</div>`;
 const fac=factionLeagueRows();$('factionRank').innerHTML=fac.map((r,i)=>`<div class="faction-score"><b>#${i+1} ${civLabel(r.civ)}</b><div class="bar"><i style="width:${clamp(r.score,0,100)}%"></i></div><b>${r.score.toFixed(1)}</b></div><div class="fine">${r.players} jugadores · PvP ${r.pvpComponent.toFixed(0)} · Industria ${r.industrialComponent.toFixed(0)} · Operaciones ${r.operationsComponent.toFixed(0)}</div>`).join('');renderLeagueSchedule();}
function resetLeague(){if(!confirm('¿Reiniciar la Liga 10? Se borran sus 8 fechas y resultados, pero NO tu Megafábrica.'))return;localStorage.removeItem(LEAGUE_KEY);league=null;ensureLeague();render();loadAllRankings();toast('Liga 10 reiniciada.');}
async function syncLeagueState(){if(!online||!user||!league)return;try{const q=await client.from('league_states').upsert({user_id:user.id,season:cfg.SEASON||'BETA-IMPERIOS-01',state:league,updated_at:new Date().toISOString()},{onConflict:'user_id,season'});if(q.error&&q.error.code!=='42P01')console.warn('sync league',q.error);}catch(e){console.warn('sync league',e);}}
async function loadLeagueRemote(){if(!online||!user)return;try{const q=await client.from('league_states').select('state').eq('user_id',user.id).eq('season',cfg.SEASON||'BETA-IMPERIOS-01').maybeSingle();if(q.data?.state){const local=loadLeague(),remote=q.data.state;const lr=local?.round||0,rr=remote?.round||0;if(rr>lr||!local){league=remote;localStorage.setItem(LEAGUE_KEY,JSON.stringify(league));}}}catch(e){console.warn('load league',e);}}

function installHoldTooltips(){
 const tip=$('holdTooltip');if(!tip)return;let timer=null,target=null;
 const hide=()=>{clearTimeout(timer);timer=null;target=null;tip.classList.remove('show');tip.setAttribute('aria-hidden','true');};
 const show=(el)=>{if(!el?.dataset.tip)return;target=el;tip.textContent=el.dataset.tip;tip.classList.add('show');tip.setAttribute('aria-hidden','false');const r=el.getBoundingClientRect(),w=Math.min(360,window.innerWidth-24);let left=Math.min(window.innerWidth-w-12,Math.max(12,r.left+r.width/2-w/2)),top=r.bottom+10;if(top+tip.offsetHeight>window.innerHeight-12)top=Math.max(12,r.top-tip.offsetHeight-10);tip.style.left=left+'px';tip.style.top=top+'px';};
 const arm=(el)=>{hide();if(!el?.dataset.tip)return;target=el;timer=setTimeout(()=>{if(target===el)show(el)},2000);};
 document.addEventListener('pointerover',e=>{const el=e.target.closest?.('[data-tip]');if(el&&!el.contains(e.relatedTarget))arm(el)});
 document.addEventListener('pointerout',e=>{const el=e.target.closest?.('[data-tip]');if(el&&!el.contains(e.relatedTarget))hide()});
 document.addEventListener('focusin',e=>{const el=e.target.closest?.('[data-tip]');if(el)arm(el)});
 document.addEventListener('focusout',hide);document.addEventListener('pointerdown',e=>{const el=e.target.closest?.('[data-tip]');if(el&&e.pointerType==='touch')arm(el)});document.addEventListener('pointerup',e=>{if(e.pointerType==='touch'&&!tip.classList.contains('show'))hide()});
 window.addEventListener('scroll',hide,{passive:true});document.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});
}
